(()=>{
  const out=[];
  // 1) 找所有 overflow:hidden 且内容溢出的容器
  document.querySelectorAll('*').forEach(e=>{
    const s=getComputedStyle(e);
    if((s.overflowY==='hidden'||s.overflow==='hidden') && e.scrollHeight>e.clientHeight+4 && e.clientHeight>0){
      out.push('CLIP: '+(e.id?'#'+e.id:'.'+(e.className||'').toString().split(' ')[0])+' clientH='+e.clientHeight+' scrollH='+e.scrollHeight+' ovf='+s.overflowY);
    }
  });
  return out.slice(0,12).join('\n  ') || 'no-clip';
})()

(()=>{
  // 2) 工具箱区域实测位置
  const ids=['cutTools','cutParams','cutList','cutCanvas','cutStage'];
  return ids.map(i=>{const e=document.getElementById(i); if(!e) return i+'=MISSING';
    const r=e.getBoundingClientRect(); return i+' top='+Math.round(r.top)+' bottom='+Math.round(r.bottom)+' h='+Math.round(r.height)+' scrollH='+e.scrollHeight+' clientH='+e.clientHeight;}).join('\n  ');
})()

(()=>{
  const e=document.querySelector('.side') || document.querySelector('aside');
  if(!e) return 'no side';
  const s=getComputedStyle(e);
  return 'side: display='+s.display+' ovf='+s.overflowY+' h='+Math.round(e.getBoundingClientRect().height)+' scrollH='+e.scrollHeight+' clientH='+e.clientHeight;
})()
